CREATE TABLE IF NOT EXISTS `cars` (`id` TEXT NOT NULL, `carNumber` TEXT NOT NULL, `modelName` TEXT NOT NULL, `nickname` TEXT, `make` TEXT NOT NULL, `modelYear` INTEGER NOT NULL, `powertrain` TEXT NOT NULL, `vehicleClass` TEXT NOT NULL, `currentMileage` INTEGER NOT NULL, `engineHours` REAL, `currentTireMode` TEXT NOT NULL, `summerTireMileage` INTEGER NOT NULL, `winterTireMileage` INTEGER NOT NULL, `lastSwapMileage` INTEGER NOT NULL, `summerTireName` TEXT, `winterTireName` TEXT, `photoUri` TEXT, `isSevereCondition` INTEGER NOT NULL, `isArchived` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `maintenance_catalog` (`itemCode` TEXT NOT NULL, `displayName` TEXT NOT NULL, `category` TEXT NOT NULL, `priority` TEXT NOT NULL, `defaultActionType` TEXT NOT NULL, `defaultIntervalKm` INTEGER, `defaultIntervalMonths` INTEGER, `severeIntervalKm` INTEGER, `severeIntervalMonths` INTEGER, `firstIntervalKm` INTEGER, `firstIntervalMonths` INTEGER, `applicablePowertrains` TEXT NOT NULL, `applicableVehicleClasses` TEXT NOT NULL, `isConditionBased` INTEGER NOT NULL, `guideNotes` TEXT, PRIMARY KEY(`itemCode`));
CREATE TABLE IF NOT EXISTS `maintenance_rules` (`id` TEXT NOT NULL, `carId` TEXT NOT NULL, `itemCode` TEXT NOT NULL, `actionType` TEXT NOT NULL, `intervalKm` INTEGER, `intervalMonths` INTEGER, `intervalHours` REAL, `firstIntervalKm` INTEGER, `firstIntervalMonths` INTEGER, `sourceType` TEXT NOT NULL, `isVerified` INTEGER NOT NULL, `isEnabled` INTEGER NOT NULL, `lastServiceDate` TEXT, `lastServiceMileage` INTEGER, `lastServiceHours` REAL, `lastConditionValue` TEXT, `userCustomNotes` TEXT, PRIMARY KEY(`id`), FOREIGN KEY(`carId`) REFERENCES `cars`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_maintenance_rules_carId` ON `maintenance_rules` (`carId`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_maintenance_rules_carId_itemCode` ON `maintenance_rules` (`carId`, `itemCode`);
CREATE TABLE IF NOT EXISTS `service_visits` (`id` TEXT NOT NULL, `carId` TEXT NOT NULL, `serviceDate` TEXT NOT NULL, `odometerKm` INTEGER NOT NULL, `engineHours` REAL, `workshop` TEXT, `totalCost` INTEGER NOT NULL, `notes` TEXT, `receiptPhotoUri` TEXT, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`carId`) REFERENCES `cars`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_service_visits_carId` ON `service_visits` (`carId`);
CREATE TABLE IF NOT EXISTS `service_lines` (`id` TEXT NOT NULL, `visitId` TEXT NOT NULL, `itemCode` TEXT NOT NULL, `actionType` TEXT NOT NULL, `partsCost` INTEGER NOT NULL, `laborCost` INTEGER NOT NULL, `conditionValue` TEXT, `partSpecification` TEXT, `notes` TEXT, PRIMARY KEY(`id`), FOREIGN KEY(`visitId`) REFERENCES `service_visits`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_service_lines_visitId` ON `service_lines` (`visitId`);
CREATE TABLE IF NOT EXISTS `tire_swap_logs` (`id` TEXT NOT NULL, `carId` TEXT NOT NULL, `swapDate` TEXT NOT NULL, `swapMileage` INTEGER NOT NULL, `fromMode` TEXT NOT NULL, `toMode` TEXT NOT NULL, `drivenDistanceDuringMode` INTEGER NOT NULL, `storageLocation` TEXT, `frontTreadDepthMm` REAL, `rearTreadDepthMm` REAL, `swapCost` INTEGER NOT NULL, `notes` TEXT, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`carId`) REFERENCES `cars`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_tire_swap_logs_carId` ON `tire_swap_logs` (`carId`);
CREATE TABLE IF NOT EXISTS `meter_readings` (`id` TEXT NOT NULL, `carId` TEXT NOT NULL, `readingDate` TEXT NOT NULL, `odometerKm` INTEGER NOT NULL, `engineHours` REAL, `inputSource` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`carId`) REFERENCES `cars`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_meter_readings_carId` ON `meter_readings` (`carId`);
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
PRAGMA user_version=2;
